     "sql": "SELECT ROUND(100.0 * COUNT_IF(result = 'Rat Activity') / COUNT(*), 1) FROM {{CATALOG}}.nyc_dohmh_food_safety.rodent_inspections WHERE inspection_type = 'Initial' AND YEAR(inspection_date) = 2025"
